- (nullable UIImage *)iconForBundleURL:(NSURL *)bundleURL {
    NSDictionary<NSString *, id> *info = [NSDictionary dictionaryWithContentsOfURL:
        [bundleURL URLByAppendingPathComponent:@"Info.plist"]];
    NSDictionary *icons = [info[@"CFBundleIcons"] isKindOfClass:[NSDictionary class]]
        ? info[@"CFBundleIcons"]
        : nil;
    NSDictionary *primaryIcon = [icons[@"CFBundlePrimaryIcon"] isKindOfClass:[NSDictionary class]]
        ? icons[@"CFBundlePrimaryIcon"]
        : nil;
    NSArray<NSString *> *iconFiles = [primaryIcon[@"CFBundleIconFiles"] isKindOfClass:[NSArray class]]
        ? primaryIcon[@"CFBundleIconFiles"]
        : ([info[@"CFBundleIconFiles"] isKindOfClass:[NSArray class]] ? info[@"CFBundleIconFiles"] : @[]);
    NSString *iconName = iconFiles.lastObject;
    NSMutableArray<NSString *> *candidateNames = [NSMutableArray array];
    if (iconName.length > 0) {
        [candidateNames addObjectsFromArray:@[
            iconName,
            [iconName stringByAppendingPathExtension:@"png"],
            [iconName stringByAppendingString:@"@2x.png"],
            [iconName stringByAppendingString:@"@3x.png"]
        ]];
    }
    NSArray<NSString *> *bundleContents = [[[NSFileManager defaultManager]
        contentsOfDirectoryAtPath:bundleURL.path
        error:nil] sortedArrayUsingSelector:@selector(localizedCaseInsensitiveCompare:)];
    for (NSString *entry in bundleContents) {
        if ([entry.pathExtension.lowercaseString isEqualToString:@"png"] &&
            [entry.lowercaseString containsString:@"icon"]) {
            [candidateNames addObject:entry];
        }
    }
    for (NSString *candidateName in candidateNames) {
        UIImage *icon = [UIImage imageWithContentsOfFile:
            [bundleURL.path stringByAppendingPathComponent:candidateName]];
        if (icon) {
            return icon;
        }
    }
    return nil;
}

- (NSInteger)eligibleExtensionCountForBundleURL:(NSURL *)bundleURL {
    NSString *pluginsPath = [bundleURL.path stringByAppendingPathComponent:@"PlugIns"];
    NSArray<NSString *> *contents = [[NSFileManager defaultManager]
        contentsOfDirectoryAtPath:pluginsPath
        error:nil];
    NSUInteger count = 0;
    for (NSString *entry in contents) {
        if ([entry.pathExtension.lowercaseString isEqualToString:@"appex"]) {
            count++;
        }
    }
    return (NSInteger)count;
}

