- (void)rebuildVisibleApps {
    NSString *query = [self.searchController.searchBar.text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];
    NSArray<PXTargetApp *> *matchingApps = self.allApps;
    if (query.length > 0) {
        NSPredicate *predicate = [NSPredicate predicateWithBlock:^BOOL(PXTargetApp *app, NSDictionary<NSString *, id> *bindings) {
            return [app.displayName localizedCaseInsensitiveContainsString:query] || [app.bundleIdentifier localizedCaseInsensitiveContainsString:query];
        }];
        matchingApps = [matchingApps filteredArrayUsingPredicate:predicate];
    }
    self.visibleUserApps = [matchingApps filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(PXTargetApp *app, NSDictionary<NSString *, id> *bindings) {
        (void)bindings;
        return !app.isSystemApp && !app.isSafariTarget;
    }]];
    self.visibleSystemApps = [matchingApps filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(PXTargetApp *app, NSDictionary<NSString *, id> *bindings) {
        (void)bindings;
        return app.isSystemApp || app.isSafariTarget;
    }]];
    NSMutableArray<NSArray<PXTargetApp *> *> *sections = [NSMutableArray array];
    NSMutableArray<NSString *> *titleKeys = [NSMutableArray array];
    if (self.visibleUserApps.count > 0) {
        [sections addObject:self.visibleUserApps];
        [titleKeys addObject:@"image.target_apps.section.user"];
    }
    if (self.visibleSystemApps.count > 0) {
        [sections addObject:self.visibleSystemApps];
        [titleKeys addObject:@"image.target_apps.section.system"];
    }
    self.visibleSections = [sections copy];
    self.visibleSectionTitleKeys = [titleKeys copy];
    if (matchingApps.count == 0) {
        self.viewState = query.length > 0 ? PXTargetAppsViewStateSearchEmpty : PXTargetAppsViewStateNoEligibleApps;
    } else {
        self.viewState = PXTargetAppsViewStateReady;
    }
    [self.tableView reloadData];
}

