    UITableViewCell *cell = [tableView dequeueReusableCellWithIdentifier:reuseIdentifier];
    if (!cell) {
        cell = [[UITableViewCell alloc] initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:reuseIdentifier];
        cell.textLabel.adjustsFontForContentSizeCategory = YES;
        cell.detailTextLabel.adjustsFontForContentSizeCategory = YES;
        cell.detailTextLabel.numberOfLines = 2;
    }
    BOOL isSelected = [self.selectedBundleIdentifiers containsObject:app.bundleIdentifier];
    UIListContentConfiguration *content = [UIListContentConfiguration subtitleCellConfiguration];
    content.text = app.isSafariTarget
        ? PXLocalizedString(@"image.target_apps.safari.title")
        : app.displayName;
    content.secondaryText = app.isSafariTarget
        ? [self detailTextForSafari]
        : [self detailTextForApp:app];
    content.image = app.icon ?: [UIImage systemImageNamed:app.isSafariTarget ? @"safari.fill" : @"app.fill"];
    content.imageProperties.maximumSize = CGSizeMake(40.0, 40.0);
    content.imageProperties.cornerRadius = 9.0;
    content.imageProperties.tintColor = app.isSafariTarget
        ? [self colorForSafariReadiness]
        : UIColor.systemBlueColor;
    content.textProperties.font = [UIFont preferredFontForTextStyle:UIFontTextStyleBody];
    content.secondaryTextProperties.font = [UIFont preferredFontForTextStyle:UIFontTextStyleFootnote];
    cell.contentConfiguration = content;
    cell.selectionStyle = UITableViewCellSelectionStyleDefault;
    cell.accessoryType = app.isSafariTarget && ![self isSafariReady]
        ? UITableViewCellAccessoryNone
        : (isSelected ? UITableViewCellAccessoryCheckmark : UITableViewCellAccessoryNone);
    cell.accessoryView = app.isSafariTarget && ![self isSafariReady]
        ? [self safariReadinessAccessoryView]
        : nil;
    cell.accessibilityIdentifier = [@"image-target-app-" stringByAppendingString:app.bundleIdentifier];
    cell.accessibilityLabel = PXLocalizedFormat(@"accessibility.settings.row", content.text, content.secondaryText);
    cell.accessibilityValue = app.isSafariTarget
        ? [self accessibilityValueForSafariSelected:isSelected]
        : (isSelected ? PXLocalizedString(@"accessibility.selected") : PXLocalizedString(@"accessibility.not_selected"));
    cell.accessibilityHint = app.isSafariTarget && ![self isSafariReady]
        ? PXLocalizedString(@"image.target_apps.safari.not_ready.hint")
        : PXLocalizedString(@"image.target_apps.selection_hint");
    cell.accessibilityTraits = UIAccessibilityTraitButton | (isSelected ? UIAccessibilityTraitSelected : 0);
    return cell;
}

- (UITableViewCell *)stateCellForTableView:(UITableView *)tableView {
    static NSString *const reuseIdentifier = @"ImageTargetAppsStateCell";
    UITableViewCell *cell = [tableView dequeueReusableCellWithIdentifier:reuseIdentifier];
    if (!cell) {
        cell = [[UITableViewCell alloc] initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:reuseIdentifier];
        cell.textLabel.adjustsFontForContentSizeCategory = YES;
        cell.detailTextLabel.adjustsFontForContentSizeCategory = YES;
        cell.detailTextLabel.numberOfLines = 0;
    }
    UIListContentConfiguration *content = [UIListContentConfiguration subtitleCellConfiguration];
    cell.selectionStyle = UITableViewCellSelectionStyleNone;
    cell.accessoryType = UITableViewCellAccessoryNone;
    cell.accessoryView = nil;
    cell.accessibilityTraits = UIAccessibilityTraitStaticText;
    if (self.viewState == PXTargetAppsViewStateLoading) {
        content.text = PXLocalizedString(@"image.target_apps.loading.title");
        content.secondaryText = PXLocalizedString(@"image.target_apps.loading.message");
        content.image = [UIImage systemImageNamed:@"arrow.triangle.2.circlepath"];
        UIActivityIndicatorView *indicator = [[UIActivityIndicatorView alloc] initWithActivityIndicatorStyle:UIActivityIndicatorViewStyleMedium];
        [indicator startAnimating];
        cell.accessoryView = indicator;
        cell.accessibilityValue = PXLocalizedString(@"home.accessibility.processing");
    } else if (self.viewState == PXTargetAppsViewStateSearchEmpty) {
        content.text = PXLocalizedString(@"image.target_apps.search_empty.title");
        content.secondaryText = PXLocalizedString(@"image.target_apps.search_empty.message");
        content.image = [UIImage systemImageNamed:@"magnifyingglass"];
    } else if (self.viewState == PXTargetAppsViewStateNoEligibleApps) {
        content.text = PXLocalizedString(@"image.target_apps.empty.title");
        content.secondaryText = PXLocalizedString(@"image.target_apps.empty.message");
        content.image = [UIImage systemImageNamed:@"app.dashed"];
    } else {
        content.text = PXLocalizedString(@"image.target_apps.failure.title");
        content.secondaryText = PXLocalizedString(@"image.target_apps.failure.message");
        content.image = [UIImage systemImageNamed:@"exclamationmark.triangle"];
        cell.selectionStyle = UITableViewCellSelectionStyleDefault;
        cell.accessibilityTraits = UIAccessibilityTraitButton;
        cell.accessibilityHint = PXLocalizedString(@"image.target_apps.failure.retry_hint");
    }
    content.imageProperties.tintColor = UIColor.systemBlueColor;
    content.textProperties.font = [UIFont preferredFontForTextStyle:UIFontTextStyleBody];
    content.secondaryTextProperties.font = [UIFont preferredFontForTextStyle:UIFontTextStyleSubheadline];
    cell.contentConfiguration = content;
    cell.accessibilityLabel = PXLocalizedFormat(@"accessibility.state", content.text, content.secondaryText);
    return cell;
}

- (void)tableView:(UITableView *)tableView didSelectRowAtIndexPath:(NSIndexPath *)indexPath {
    [tableView deselectRowAtIndexPath:indexPath animated:YES];
    if (self.viewState == PXTargetAppsViewStateEnumerationFailure) {
        [self loadLocalApps];
        return;
    }
    if (self.viewState != PXTargetAppsViewStateReady) {
        return;
    }
    PXTargetApp *app = [self appForIndexPath:indexPath];
    if (app.isSafariTarget) {
        [self handleSafariSelectionForApp:app];
        return;
    }
    [self toggleSelectionForApp:app];
}

- (PXTargetApp *)appForIndexPath:(NSIndexPath *)indexPath {
    return self.visibleSections[(NSUInteger)indexPath.section][(NSUInteger)indexPath.row];
}

- (void)refreshSafariReadiness {
    PXSafariTargetReadiness *readiness = [self.safariReadinessProvider currentSafariTargetReadiness];
    self.safariReadiness = readiness ?: [[PXSafariTargetReadiness alloc]
        initWithState:PXSafariTargetReadinessStateUnknown];
}

- (BOOL)isSafariReady {
    return self.safariReadiness.state == PXSafariTargetReadinessStateReady;
}

- (void)handleSafariSelectionForApp:(PXTargetApp *)app {
    BOOL isSelected = [self.selectedBundleIdentifiers containsObject:app.bundleIdentifier];
    if (isSelected) {
        [self toggleSelectionForApp:app];
        return;
    }
    if (![self isSafariReady]) {
        [self presentSafariNotReadyExplanation];
        return;
    }
    [self presentSafariSelectionExplanationForApp:app];
}

- (void)presentSafariNotReadyExplanation {
    UIAlertController *alert = [UIAlertController
        alertControllerWithTitle:[self titleForSafariReadiness]
        message:[self detailForSafariReadiness]
        preferredStyle:UIAlertControllerStyleAlert];
    [alert addAction:[UIAlertAction actionWithTitle:PXLocalizedString(@"navigation.close")
                                             style:UIAlertActionStyleCancel
                                           handler:nil]];
    [alert addAction:[UIAlertAction
        actionWithTitle:PXLocalizedString(@"image.target_apps.safari.not_ready.recovery")
                  style:UIAlertActionStyleDefault
                handler:^(UIAlertAction *action) {
                    (void)action;
                    [self handleSafariReadinessRefresh];
                }]];
    [self presentViewController:alert animated:YES completion:nil];
    UIAccessibilityPostNotification(UIAccessibilityAnnouncementNotification,
                                    PXLocalizedString(@"image.target_apps.safari.not_ready.announcement"));
}

- (void)handleSafariReadinessRefresh {
    [self refreshSafariReadiness];
    [self.tableView reloadData];
    UIAccessibilityPostNotification(UIAccessibilityAnnouncementNotification,
                                    [self titleForSafariReadiness]);
}

- (void)presentSafariSelectionExplanationForApp:(PXTargetApp *)app {
    UIAlertController *alert = [UIAlertController
        alertControllerWithTitle:PXLocalizedString(@"image.target_apps.safari.confirmation.title")
        message:PXLocalizedString(@"image.target_apps.safari.confirmation.message")
        preferredStyle:UIAlertControllerStyleAlert];
    [alert addAction:[UIAlertAction actionWithTitle:PXLocalizedString(@"navigation.cancel")
                                             style:UIAlertActionStyleCancel
                                           handler:nil]];
    [alert addAction:[UIAlertAction
        actionWithTitle:PXLocalizedString(@"image.target_apps.safari.confirmation.action")
                  style:UIAlertActionStyleDefault
                handler:^(UIAlertAction *action) {
                    (void)action;
                    [self handleConfirmedSafariSelectionForApp:app];
                }]];
    [self presentViewController:alert animated:YES completion:nil];
}

- (void)handleConfirmedSafariSelectionForApp:(PXTargetApp *)app {
    [self toggleSelectionForApp:app];
}

- (void)toggleSelectionForApp:(PXTargetApp *)app {
    BOOL wasSelected = [self.selectedBundleIdentifiers containsObject:app.bundleIdentifier];
    NSError *persistenceError = nil;
    if (![[IdentifierManager sharedManager]
        setApplicationInScope:app.bundleIdentifier
        enabled:!wasSelected
        error:&persistenceError]) {
        [self.tableView reloadData];
        NSLog(@"[ProjectX] Target App selection persistence failed: %@",
              persistenceError.localizedDescription);
        UIAccessibilityPostNotification(UIAccessibilityAnnouncementNotification,
                                        PXLocalizedString(@"image.target_apps.persistence_failed.announcement"));
        UIAlertController *alert = [UIAlertController
            alertControllerWithTitle:PXLocalizedString(@"image.target_apps.persistence_failed.title")
            message:PXLocalizedString(@"image.target_apps.persistence_failed.message")
            preferredStyle:UIAlertControllerStyleAlert];
        [alert addAction:[UIAlertAction actionWithTitle:PXLocalizedString(@"navigation.close")
                                                style:UIAlertActionStyleCancel
                                              handler:nil]];
        [self presentViewController:alert animated:YES completion:nil];
        return;
    }
    if (wasSelected) {
        [self.selectedBundleIdentifiers removeObject:app.bundleIdentifier];
    } else {
        [self.selectedBundleIdentifiers addObject:app.bundleIdentifier];
    }
    if (self.selectionCompletion) {
        self.selectionCompletion([self.selectedBundleIdentifiers copy]);
    }
    [self.tableView reloadData];
    UIAccessibilityPostNotification(UIAccessibilityAnnouncementNotification, wasSelected
        ? PXLocalizedString(@"image.target_apps.deselected_announcement")
        : PXLocalizedString(@"image.target_apps.selected_announcement"));
}

- (NSString *)detailTextForApp:(PXTargetApp *)app {
    if (app.eligibleExtensionCount == 1) {
        return PXLocalizedFormat(@"image.target_apps.extension_one", app.bundleIdentifier);
    }
    if (app.eligibleExtensionCount > 1) {
        return PXLocalizedFormat(@"image.target_apps.extension_count", app.bundleIdentifier, (long)app.eligibleExtensionCount);
    }
    return app.bundleIdentifier;
}

- (NSString *)detailTextForSafari {
    return PXLocalizedFormat(@"image.target_apps.safari.detail_format",
        PXLocalizedString(@"image.target_apps.safari.identity"),
        [self titleForSafariReadiness]);
}

- (NSString *)titleForSafariReadiness {
    switch (self.safariReadiness.state) {
        case PXSafariTargetReadinessStateReady:
            return PXLocalizedString(@"image.target_apps.safari.ready.title");
        case PXSafariTargetReadinessStateInjectionUnavailable:
            return PXLocalizedString(@"image.target_apps.safari.injection_unavailable.title");
        case PXSafariTargetReadinessStateWebKitAttributionUnavailable:
            return PXLocalizedString(@"image.target_apps.safari.webkit_unavailable.title");
        case PXSafariTargetReadinessStateSafariLibraryAccessUnavailable:
            return PXLocalizedString(@"image.target_apps.safari.library_unavailable.title");
        case PXSafariTargetReadinessStateCleanupPartiallyFailed:
            return PXLocalizedString(@"image.target_apps.safari.cleanup_partial.title");
        case PXSafariTargetReadinessStateActiveGenerationMismatch:
            return PXLocalizedString(@"image.target_apps.safari.generation_mismatch.title");
        case PXSafariTargetReadinessStateUnknown:
            return PXLocalizedString(@"image.target_apps.safari.unknown.title");
    }
}

- (NSString *)detailForSafariReadiness {
    switch (self.safariReadiness.state) {
        case PXSafariTargetReadinessStateReady:
            return PXLocalizedString(@"image.target_apps.safari.ready.detail");
        case PXSafariTargetReadinessStateInjectionUnavailable:
            return PXLocalizedString(@"image.target_apps.safari.injection_unavailable.detail");
        case PXSafariTargetReadinessStateWebKitAttributionUnavailable:
            return PXLocalizedString(@"image.target_apps.safari.webkit_unavailable.detail");
        case PXSafariTargetReadinessStateSafariLibraryAccessUnavailable:
            return PXLocalizedString(@"image.target_apps.safari.library_unavailable.detail");
        case PXSafariTargetReadinessStateCleanupPartiallyFailed:
            return PXLocalizedString(@"image.target_apps.safari.cleanup_partial.detail");
        case PXSafariTargetReadinessStateActiveGenerationMismatch:
            return PXLocalizedString(@"image.target_apps.safari.generation_mismatch.detail");
        case PXSafariTargetReadinessStateUnknown:
            return PXLocalizedString(@"image.target_apps.safari.unknown.detail");
    }
}

- (UIColor *)colorForSafariReadiness {
    switch (self.safariReadiness.state) {
        case PXSafariTargetReadinessStateReady:
            return UIColor.systemGreenColor;
        case PXSafariTargetReadinessStateUnknown:
            return UIColor.systemBlueColor;
        case PXSafariTargetReadinessStateInjectionUnavailable:
        case PXSafariTargetReadinessStateWebKitAttributionUnavailable:
        case PXSafariTargetReadinessStateSafariLibraryAccessUnavailable:
        case PXSafariTargetReadinessStateCleanupPartiallyFailed:
        case PXSafariTargetReadinessStateActiveGenerationMismatch:
            return UIColor.systemOrangeColor;
    }
}

- (UIImageView *)safariReadinessAccessoryView {
    UIImageView *accessory = [[UIImageView alloc] initWithImage:[UIImage
        systemImageNamed:self.safariReadiness.state == PXSafariTargetReadinessStateUnknown
            ? @"questionmark.circle.fill"
            : @"exclamationmark.triangle.fill"]];
    accessory.tintColor = [self colorForSafariReadiness];
    accessory.frame = CGRectMake(0.0, 0.0, 24.0, 24.0);
    accessory.isAccessibilityElement = NO;
    return accessory;
}

- (NSString *)accessibilityValueForSafariSelected:(BOOL)isSelected {
    NSString *selection = isSelected
        ? PXLocalizedString(@"accessibility.selected")
        : PXLocalizedString(@"accessibility.not_selected");
    return PXLocalizedFormat(@"image.target_apps.safari.accessibility.value",
        selection,
        [self titleForSafariReadiness]);
}

@end
